//! Fixed keys, nonces and expected bytes, so the phone's core (Dart, Swift, Kotlin through the same crate or a port)
//! can reproduce them. `vectors.json` is committed and never regenerated by a test run: when the wire format changes
//! on purpose, run `cargo test --test vectors -- --ignored print_vectors` and review the diff.
//! Signature vectors are verify-only: hardware ECDSA is not deterministic.

use bobix_link::command;
use bobix_link::envelope::{seal_with_tail, Direction, Lane, Stream, VersionRange};
use bobix_link::messages::{prompt_hash, shown_hash, shown_hash_with_files, Choice, CommandBody, PlanFile, Question, MAX_NOTE};
use bobix_link::pairing::{normalize_relay_url, hello_body, hello_mac_input, Hello, PairingCode, Rights};
use bobix_link::messages::PhoneMsg;
use bobix_link::keys::{soft::SoftSigner, Identity, SignPublic};
use bobix_link::{b64, hex};
use crypto_box::{PublicKey, SecretKey};
use serde_json::{json, Value};

const FILE: &str = include_str!("vectors.json");

fn seed(n: u8) -> [u8; 32] {
    [n; 32]
}

fn question(options: &[&str], multi: bool) -> Question {
    Question { text: "Which database?".into(), options: options.iter().map(|s| s.to_string()).collect(), multi_select: multi }
}

pub fn build() -> Value {
    let desktop = Identity::from_secrets(seed(1), seed(2));
    let phone = Identity::from_secrets(seed(3), seed(4));
    let (dp, pp) = (desktop.public(), phone.public());

    let envelope = |dir, stream, counter: u64, tail: u8, text: &str| {
        let (sender, recipient) = if dir == Direction::ToPhone { (seed(2), pp.boxk) } else { (seed(4), dp.boxk) };
        let packet = seal_with_tail(
            1,
            Lane { dir, stream },
            counter,
            [tail; 14],
            &SecretKey::from(sender),
            &PublicKey::from(recipient),
            text.as_bytes(),
        );
        json!({ "version": 1, "dir": format!("{dir:?}"), "stream": format!("{stream:?}"), "counter": counter,
                "laneByte": Lane { dir, stream }.to_byte(), "tail": hex(&[tail; 14]), "plaintext": text, "packet": hex(&packet) })
    };

    let signer = SoftSigner::from_secret(&seed(5)).expect("valid P-256 scalar");
    let sign_msg = b"bobix test vector message";
    // Protocol pieces built from the same keys.
    let code = PairingCode::with_secret("wss://relay.example/ws", dp, seed(6)).unwrap();
    let rights = Rights { answer: true, plan: true, question: false, start: false, stop: true, activity: true };
    let hello = Hello::new(&code, &pp, &signer.public(), "Test phone", rights, VersionRange { min: 1, max: 1 });
    let body = CommandBody::Answer { id: "req1".into(), choice: Choice::Allow, shown: "abc".into() };
    let body_text = serde_json::to_string(&body).unwrap();
    let cid = hex(&[7u8; 16]);
    let cmd_bytes = command::command_bytes(1, &pp.device_id(), &dp.device_id(), body.kind(), &body.target(), &cid, 4242, 1_800_000_000_000, &body_text);
    let cmd = command::build_with_cid(cid.clone(), 1, &pp.device_id(), &dp.device_id(), 4242, 1_800_000_000_000, &body, |m| signer.sign(m));
    let hello_packet = seal_with_tail(
        1, Lane { dir: Direction::ToDesktop, stream: Stream::Event }, 11, [0xb1; 14],
        &SecretKey::from(seed(4)), &PublicKey::from(dp.boxk), &PhoneMsg::Hello(hello.clone()).to_json(),
    );
    let sign_pub = signer.public().to_sec1();
    // Negative vectors: each must be refused (or, for the signature, accepted although S is high).
    let first = envelope(Direction::ToPhone, Stream::Event, 42, 0xa2, "{\"kind\":\"paired\"}");
    let packet_hex = first["packet"].as_str().unwrap().to_string();
    let mut tampered = bobix_link::unhex(&packet_hex).unwrap();
    let last = tampered.len() - 1;
    tampered[last] ^= 1;
    let low = p256::ecdsa::Signature::from_der(&signer.sign(sign_msg)).unwrap().normalize_s();
    let (r, s) = low.split_scalars();
    let high = p256::ecdsa::Signature::from_scalars(r, -*s).unwrap();
    let low_order: Vec<String> = (0..3u8).map(|i| { let mut k = [0xffu8; 32]; k[0] = 0xec + i; k[31] = 0x7f; hex(&k) })
        .chain([hex(&[0u8; 32]), hex(&{ let mut o = [0u8; 32]; o[0] = 1; o })]).collect();
    json!({
        "negative": {
            "tamperedPacket": { "packet": hex(&tampered), "openedBy": "phone", "expect": "decrypt-failure" },
            "reflectedPacket": { "packet": packet_hex, "openedBy": "desktop", "expect": "refused: its own direction (lane bit 7 = 0 means desktop to phone)" },
            "highSSignature": { "message": hex(sign_msg), "signatureDer": hex(high.to_der().as_bytes()), "expect": "verifies (S is not normalised by the secure hardware)" },
            "lowOrderBoxKeys": { "keys": low_order, "expect": "refused as a box public key: the shared secret would be all zeros" },
        },
        "protocol": {
            "helloMacInput": hex(&hello_mac_input(&dp, &pp, &sign_pub, "Test phone", rights)),
            "helloBody": { "phoneBoxPublic": hex(&pp.boxk), "packet": hex(&hello_packet), "body": hex(&hello_body(&pp.boxk, &hello_packet)),
                            "note": "the body is the 32-byte phone box key followed by the sealed packet; the packet carries the hello JSON" },
            "pairingSecret": hex(&seed(6)), "pairingUri": code.to_uri(),
            "relayToken": hex(&code.relay_token()), "relayTokenHash": hex(&code.relay_token_hash()), "macKey": hex(&code.mac_key()),
            "hello": hello, "rightsMask": rights.to_mask(),
            "commandBody": body_text, "cid": cid, "commandCounter": 4242, "issuedAt": 1_800_000_000_000u64,
            "commandSignedBytes": hex(&cmd_bytes),
            "command": cmd, "commandNote": "`command.sig` is verify-only; the bytes it signs are `commandSignedBytes`",
            "byeBytes": hex(&command::bye_bytes(1, &pp.device_id(), &dp.device_id(), 9)),
            "authBytes": hex(&command::auth_bytes("wss://Relay.Example:443/", "challenge-1").unwrap()),
            "shown": [
                { "what": "toolInput", "text": "ls -la", "cut": false, "questions": [], "shown": shown_hash("ls -la", false, &[]) },
                { "what": "toolInput", "text": "ls -la", "cut": true, "questions": [], "shown": shown_hash("ls -la", true, &[]) },
                { "what": "question", "text": "Which database?", "cut": false, "questions": [question(&["SQLite", "Postgres"], false)],
                  "shown": shown_hash("Which database?", false, &[question(&["SQLite", "Postgres"], false)]) },
                { "what": "question", "text": "Which database?", "cut": false, "questions": [question(&["Postgres", "SQLite"], false)],
                  "shown": shown_hash("Which database?", false, &[question(&["Postgres", "SQLite"], false)]) },
                { "what": "question", "text": "Which database?", "cut": false, "questions": [question(&["SQLite", "Postgres"], true)],
                  "shown": shown_hash("Which database?", false, &[question(&["SQLite", "Postgres"], true)]) },
                { "what": "plan", "text": "# Plan\nstep \\u{202e}", "cut": false, "questions": [], "shown": shown_hash("# Plan\nstep \\u{202e}", false, &[]),
                  "note": "the text is the displayed form: hidden characters are already visible escapes" },
                { "what": "plan", "text": "# Plan", "cut": false, "questions": [], "files": plan_files_json(), "shown": shown_hash_with_files("# Plan", false, &[], &plan_files()),
                  "note": "a plan with files: each file's name, path, bytes, text, cut and sent follow the questions" },
            ],
            "shownNote": "shown = hex SHA-256 of Fields(\"bobix-shown-v1\", text, cut as u64, number of questions, then per question: text, multiSelect as u64, number of options, each option; then, only when the plan has files: \"files\", the number of files and per file: name, path, bytes as u64, text, cut as u64, sent as u64); numbers are u64 big endian as 8-byte fields; every field has a u32 big endian length prefix",
            "limits": { "maxNote": MAX_NOTE, "note": "the longest plan note and the longest answer to a question, in UTF-8 bytes" },
            "promptHash": { "prompt": "Implement ticket 12.", "hash": prompt_hash("Implement ticket 12.") },
            "authBytesRelayUrl": "wss://relay.example", "authChallenge": "challenge-1",
            "authSignature": hex(&desktop.sign_auth(&command::auth_bytes("wss://relay.example", "challenge-1").unwrap())),
            "relayUrlNormalisation": [
                ["wss://Relay.Example", "wss://relay.example"], ["WSS://relay.example:443/", "wss://relay.example"],
                ["wss://relay.example:8443/ws/", "wss://relay.example:8443/ws"], ["wss://relay.example:0443/ws//", "wss://relay.example/ws"],
                ["wss://relay.example/Ws?Token=A#frag", "wss://relay.example/Ws?Token=A"], ["ws://127.0.0.1:8787/", "ws://localhost:8787"],
                ["ws://[::1]:8787", "ws://localhost:8787"], ["ws://localhost:80", "ws://localhost"], ["wss://[2001:DB8::1]:9000/x", "wss://[2001:db8::1]:9000/x"],
            ],
            "relayUrlRefused": ["ws://relay.example", "http://relay.example", "wss://a@b", "wss://relay.example:99999", "wss://", "wss://relay.example:+443", "wss://2001:db8::1", "wss://a:b:443", "wss://relay.exa\tmple", "wss://RÉLAY.example"],
        },
        "note": "Binary values are hex, except the parts of the pairing URI, the hello fields (auth, boxk, sign, mac) and command.sig, which are URL-safe base64 without padding (cid is hex). Secrets are 32 bytes of one repeated value. laneByte = bit 7 (1: phone to desktop) | stream (0 state, 1 event, 2 activity).",
        "desktop": { "authSeed": hex(&seed(1)), "boxSecret": hex(&seed(2)), "authPublic": hex(&dp.auth),
                      "boxPublic": hex(&dp.boxk), "deviceId": dp.device_id() },
        "phone": { "authSeed": hex(&seed(3)), "boxSecret": hex(&seed(4)), "authPublic": hex(&pp.auth),
                    "boxPublic": hex(&pp.boxk), "deviceId": pp.device_id(),
                    "signSecret": hex(&seed(5)), "signPublicSec1": hex(&signer.public().to_sec1()) },
        "authSignature": { "message": hex(b"bobix test challenge"), "signer": "desktop",
                            "signature": hex(&desktop.sign_auth(b"bobix test challenge")) },
        "envelopes": [
            envelope(Direction::ToPhone, Stream::State, 1_800_000_000_001, 0xa1, "{\"kind\":\"home\"}"),
            envelope(Direction::ToPhone, Stream::Event, 42, 0xa2, "{\"kind\":\"paired\"}"),
            envelope(Direction::ToDesktop, Stream::Event, 7, 0xa3, "{\"kind\":\"sync\",\"waiting\":[]}"),
            envelope(Direction::ToPhone, Stream::Activity, 9, 0xa4, "{\"kind\":\"notice\"}"),
        ],
        "p256": { "message": hex(sign_msg), "signatureDer": hex(&signer.sign(sign_msg)),
                   "note": "verify-only; the signature changes with the nonce" },
        "base64Example": { "bytes": hex(&[0xfb, 0xff, 0xfe]), "text": b64(&[0xfb, 0xff, 0xfe]) },
    })
}

#[test]
fn committed_vectors_are_reproduced_exactly() {
    let committed: Value = serde_json::from_str(FILE).expect("vectors.json is JSON");
    let mut now = build();
    // ECDSA is not deterministic here either: only its verification is part of the vectors.
    now["p256"]["signatureDer"] = committed["p256"]["signatureDer"].clone();
    now["protocol"]["command"]["sig"] = committed["protocol"]["command"]["sig"].clone();
    now["negative"]["highSSignature"]["signatureDer"] = committed["negative"]["highSSignature"]["signatureDer"].clone();
    assert_eq!(now, committed);
}

#[test]
fn committed_signature_vectors_verify() {
    let v: Value = serde_json::from_str(FILE).unwrap();
    let key = SignPublic::from_sec1(&bobix_link::unhex(v["phone"]["signPublicSec1"].as_str().unwrap()).unwrap()).unwrap();
    let msg = bobix_link::unhex(v["p256"]["message"].as_str().unwrap()).unwrap();
    let sig = bobix_link::unhex(v["p256"]["signatureDer"].as_str().unwrap()).unwrap();
    assert_eq!(key.verify(&msg, &sig), Ok(()));
    let a = bobix_link::unhex(v["desktop"]["authPublic"].as_str().unwrap()).unwrap();
    let m = bobix_link::unhex(v["authSignature"]["message"].as_str().unwrap()).unwrap();
    let s = bobix_link::unhex(v["authSignature"]["signature"].as_str().unwrap()).unwrap();
    assert!(bobix_link::keys::verify_auth(&a.try_into().unwrap(), &m, &s));
}

#[test]
fn committed_command_verifies_against_the_committed_bytes() {
    let v: Value = serde_json::from_str(FILE).unwrap();
    let p = &v["protocol"];
    let key = SignPublic::from_sec1(&bobix_link::unhex(v["phone"]["signPublicSec1"].as_str().unwrap()).unwrap()).unwrap();
    let bytes = bobix_link::unhex(p["commandSignedBytes"].as_str().unwrap()).unwrap();
    let sig = bobix_link::b64_decode(p["command"]["sig"].as_str().unwrap()).unwrap();
    assert_eq!(key.verify(&bytes, &sig), Ok(()));
    let cmd: command::Command = serde_json::from_value(p["command"].clone()).unwrap();
    let ctx = command::VerifyCtx {
        version: 1, phone_id: v["phone"]["deviceId"].as_str().unwrap(), computer_id: v["desktop"]["deviceId"].as_str().unwrap(),
        sign_key: &key, counter: 4242, now_ms: 1_800_000_000_000,
    };
    assert!(command::verify(&ctx, &cmd).is_ok());
}

/// The committed packets open with the committed keys.
#[test]
fn committed_envelopes_open() {
    use bobix_link::counters::RecvState;
    use bobix_link::envelope::{VersionRange, CURRENT_VERSION};
    use bobix_link::link::Link;
    let v: Value = serde_json::from_str(FILE).unwrap();
    let get = |p: &str, k: &str| -> [u8; 32] { bobix_link::unhex(v[p][k].as_str().unwrap()).unwrap().try_into().unwrap() };
    let mut phone = Link::new(
        Direction::ToDesktop, get("phone", "boxSecret"), get("desktop", "boxPublic"),
        CURRENT_VERSION, VersionRange::current(), [0; 3], 0, RecvState::default(),
    );
    let mut desktop = Link::new(
        Direction::ToPhone, get("desktop", "boxSecret"), get("phone", "boxPublic"),
        CURRENT_VERSION, VersionRange::current(), [0; 3], 0, RecvState::default(),
    );
    for e in v["envelopes"].as_array().unwrap() {
        let packet = bobix_link::unhex(e["packet"].as_str().unwrap()).unwrap();
        let opened = if e["dir"] == "ToPhone" { phone.open(&packet) } else { desktop.open(&packet) }.unwrap();
        assert_eq!(opened.plaintext, e["plaintext"].as_str().unwrap().as_bytes());
        assert_eq!(opened.counter, e["counter"].as_u64().unwrap());
    }
}

#[test]
fn committed_negative_vectors_are_refused_or_accepted_as_stated() {
    use bobix_link::counters::RecvState;
    use bobix_link::envelope::{OpenError, CURRENT_VERSION};
    use bobix_link::link::Link;
    let v: Value = serde_json::from_str(FILE).unwrap();
    let get = |p: &str, k: &str| -> [u8; 32] { bobix_link::unhex(v[p][k].as_str().unwrap()).unwrap().try_into().unwrap() };
    let n = &v["negative"];
    let mut phone = Link::new(Direction::ToDesktop, get("phone", "boxSecret"), get("desktop", "boxPublic"), CURRENT_VERSION, VersionRange::current(), [0; 3], 0, RecvState::default());
    let mut desktop = Link::new(Direction::ToPhone, get("desktop", "boxSecret"), get("phone", "boxPublic"), CURRENT_VERSION, VersionRange::current(), [0; 3], 0, RecvState::default());
    let tampered = bobix_link::unhex(n["tamperedPacket"]["packet"].as_str().unwrap()).unwrap();
    assert_eq!(phone.open(&tampered).unwrap_err(), OpenError::Decrypt);
    let reflected = bobix_link::unhex(n["reflectedPacket"]["packet"].as_str().unwrap()).unwrap();
    assert_eq!(desktop.open(&reflected).unwrap_err(), OpenError::Reflected);
    let key = SignPublic::from_sec1(&bobix_link::unhex(v["phone"]["signPublicSec1"].as_str().unwrap()).unwrap()).unwrap();
    let high = bobix_link::unhex(n["highSSignature"]["signatureDer"].as_str().unwrap()).unwrap();
    let msg = bobix_link::unhex(n["highSSignature"]["message"].as_str().unwrap()).unwrap();
    assert_eq!(key.verify(&msg, &high), Ok(()));
    for k in n["lowOrderBoxKeys"]["keys"].as_array().unwrap() {
        let k: [u8; 32] = bobix_link::unhex(k.as_str().unwrap()).unwrap().try_into().unwrap();
        assert!(bobix_link::keys::box_public(k).is_none());
    }
    // the hello body opens with the committed keys and its MAC input is the committed bytes
    let p = &v["protocol"];
    let body = bobix_link::unhex(p["helloBody"]["body"].as_str().unwrap()).unwrap();
    let (phone_box, packet) = bobix_link::pairing::split_hello_body(&body).unwrap();
    assert_eq!(phone_box, get("phone", "boxPublic"));
    assert!(desktop.open(packet).is_ok());
    assert!(!p["helloMacInput"].as_str().unwrap().is_empty());
    // the `shown` encoding: recomputed from the committed content
    for e in p["shown"].as_array().unwrap() {
        let qs: Vec<Question> = serde_json::from_value(e["questions"].clone()).unwrap();
        let files: Vec<PlanFile> = serde_json::from_value(e.get("files").cloned().unwrap_or(json!([]))).unwrap();
        assert_eq!(shown_hash_with_files(e["text"].as_str().unwrap(), e["cut"].as_bool().unwrap(), &qs, &files), e["shown"].as_str().unwrap());
    }
    assert_eq!(p["limits"]["maxNote"], MAX_NOTE);
    assert_eq!(prompt_hash(p["promptHash"]["prompt"].as_str().unwrap()), p["promptHash"]["hash"].as_str().unwrap());
    // the relay address normalisation and the bytes the auth frame signs
    for pair in p["relayUrlNormalisation"].as_array().unwrap() {
        assert_eq!(normalize_relay_url(pair[0].as_str().unwrap()).as_deref(), pair[1].as_str());
    }
    for bad in p["relayUrlRefused"].as_array().unwrap() {
        assert_eq!(normalize_relay_url(bad.as_str().unwrap()), None);
    }
    let bytes = command::auth_bytes(p["authBytesRelayUrl"].as_str().unwrap(), p["authChallenge"].as_str().unwrap()).unwrap();
    assert_eq!(bobix_link::hex(&bytes), p["authBytes"].as_str().unwrap());
    let sig = bobix_link::unhex(p["authSignature"].as_str().unwrap()).unwrap();
    assert!(bobix_link::keys::verify_auth(&get("desktop", "authPublic"), &bytes, &sig));
}

fn plan_files() -> Vec<PlanFile> {
    vec![
        PlanFile { name: "phase-01.md".into(), path: "plans/x/phase-01.md".into(), bytes: 31, text: "## Phase 1\nDo the first thing.".into(), cut: false, sent: true },
        PlanFile { name: "phase-02.md".into(), path: "plans/x/phase-02.md".into(), bytes: 52_430, text: String::new(), cut: false, sent: false },
    ]
}

fn plan_files_json() -> Value {
    serde_json::to_value(plan_files()).unwrap()
}

#[test]
#[ignore = "prints vectors.json for review; never run by CI"]
fn print_vectors() {
    println!("{}", serde_json::to_string_pretty(&build()).unwrap());
}
